            nxt[i + 1] = (nxt[i + 1] + v * cd) % MOD
        D = nxt

    m = len(digits)
    P = [0] * m
    for d in digits:
        cd = c[d]
        q = [0] * m
        q[0] = 1
        for i in range(1, m):
            q[i] = (D[i] - cd * q[i - 1]) % MOD

        coef = count[d] * cd % MOD
        for i in range(m):
